-- NovaMart step 5D: verify staging and analytic output counts and financial reconciliation.
-- Every CHECK_RESULT should be PASS. These expected values are from NovaMart_Datasets.zip.
USE DATABASE NOVAMART_DB;

-- 22 staging views should preserve raw row counts (view objects themselves hold no data).
WITH staging_counts AS (
    SELECT 'DIM_CALENDAR' AS TABLE_NAME, (SELECT COUNT(*) FROM NOVAMART_DB.RAW.DIM_CALENDAR) AS RAW_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.STAGING.STG_DIM_CALENDAR) AS STAGING_ROWS
    UNION ALL SELECT 'DIM_CAMPAIGNS' AS TABLE_NAME, (SELECT COUNT(*) FROM NOVAMART_DB.RAW.DIM_CAMPAIGNS) AS RAW_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.STAGING.STG_DIM_CAMPAIGNS) AS STAGING_ROWS
    UNION ALL SELECT 'DIM_CATEGORIES' AS TABLE_NAME, (SELECT COUNT(*) FROM NOVAMART_DB.RAW.DIM_CATEGORIES) AS RAW_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.STAGING.STG_DIM_CATEGORIES) AS STAGING_ROWS
    UNION ALL SELECT 'DIM_CUSTOMERS' AS TABLE_NAME, (SELECT COUNT(*) FROM NOVAMART_DB.RAW.DIM_CUSTOMERS) AS RAW_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.STAGING.STG_DIM_CUSTOMERS) AS STAGING_ROWS
    UNION ALL SELECT 'DIM_PRODUCTS' AS TABLE_NAME, (SELECT COUNT(*) FROM NOVAMART_DB.RAW.DIM_PRODUCTS) AS RAW_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.STAGING.STG_DIM_PRODUCTS) AS STAGING_ROWS
    UNION ALL SELECT 'DIM_STORES' AS TABLE_NAME, (SELECT COUNT(*) FROM NOVAMART_DB.RAW.DIM_STORES) AS RAW_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.STAGING.STG_DIM_STORES) AS STAGING_ROWS
    UNION ALL SELECT 'DIM_SUPPLIERS' AS TABLE_NAME, (SELECT COUNT(*) FROM NOVAMART_DB.RAW.DIM_SUPPLIERS) AS RAW_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.STAGING.STG_DIM_SUPPLIERS) AS STAGING_ROWS
    UNION ALL SELECT 'DIM_WAREHOUSES' AS TABLE_NAME, (SELECT COUNT(*) FROM NOVAMART_DB.RAW.DIM_WAREHOUSES) AS RAW_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.STAGING.STG_DIM_WAREHOUSES) AS STAGING_ROWS
    UNION ALL SELECT 'FACT_CAMPAIGN_SPEND' AS TABLE_NAME, (SELECT COUNT(*) FROM NOVAMART_DB.RAW.FACT_CAMPAIGN_SPEND) AS RAW_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.STAGING.STG_FACT_CAMPAIGN_SPEND) AS STAGING_ROWS
    UNION ALL SELECT 'FACT_DELIVERY_EVENTS' AS TABLE_NAME, (SELECT COUNT(*) FROM NOVAMART_DB.RAW.FACT_DELIVERY_EVENTS) AS RAW_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.STAGING.STG_FACT_DELIVERY_EVENTS) AS STAGING_ROWS
    UNION ALL SELECT 'FACT_INVENTORY_MOVEMENTS' AS TABLE_NAME, (SELECT COUNT(*) FROM NOVAMART_DB.RAW.FACT_INVENTORY_MOVEMENTS) AS RAW_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.STAGING.STG_FACT_INVENTORY_MOVEMENTS) AS STAGING_ROWS
    UNION ALL SELECT 'FACT_INVENTORY_SNAPSHOT' AS TABLE_NAME, (SELECT COUNT(*) FROM NOVAMART_DB.RAW.FACT_INVENTORY_SNAPSHOT) AS RAW_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.STAGING.STG_FACT_INVENTORY_SNAPSHOT) AS STAGING_ROWS
    UNION ALL SELECT 'FACT_ORDERS' AS TABLE_NAME, (SELECT COUNT(*) FROM NOVAMART_DB.RAW.FACT_ORDERS) AS RAW_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.STAGING.STG_FACT_ORDERS) AS STAGING_ROWS
    UNION ALL SELECT 'FACT_ORDER_ATTRIBUTION' AS TABLE_NAME, (SELECT COUNT(*) FROM NOVAMART_DB.RAW.FACT_ORDER_ATTRIBUTION) AS RAW_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.STAGING.STG_FACT_ORDER_ATTRIBUTION) AS STAGING_ROWS
    UNION ALL SELECT 'FACT_ORDER_ITEMS' AS TABLE_NAME, (SELECT COUNT(*) FROM NOVAMART_DB.RAW.FACT_ORDER_ITEMS) AS RAW_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.STAGING.STG_FACT_ORDER_ITEMS) AS STAGING_ROWS
    UNION ALL SELECT 'FACT_PAYMENTS' AS TABLE_NAME, (SELECT COUNT(*) FROM NOVAMART_DB.RAW.FACT_PAYMENTS) AS RAW_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.STAGING.STG_FACT_PAYMENTS) AS STAGING_ROWS
    UNION ALL SELECT 'FACT_PURCHASE_ORDERS' AS TABLE_NAME, (SELECT COUNT(*) FROM NOVAMART_DB.RAW.FACT_PURCHASE_ORDERS) AS RAW_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.STAGING.STG_FACT_PURCHASE_ORDERS) AS STAGING_ROWS
    UNION ALL SELECT 'FACT_PURCHASE_ORDER_ITEMS' AS TABLE_NAME, (SELECT COUNT(*) FROM NOVAMART_DB.RAW.FACT_PURCHASE_ORDER_ITEMS) AS RAW_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.STAGING.STG_FACT_PURCHASE_ORDER_ITEMS) AS STAGING_ROWS
    UNION ALL SELECT 'FACT_REFUNDS' AS TABLE_NAME, (SELECT COUNT(*) FROM NOVAMART_DB.RAW.FACT_REFUNDS) AS RAW_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.STAGING.STG_FACT_REFUNDS) AS STAGING_ROWS
    UNION ALL SELECT 'FACT_RETURNS' AS TABLE_NAME, (SELECT COUNT(*) FROM NOVAMART_DB.RAW.FACT_RETURNS) AS RAW_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.STAGING.STG_FACT_RETURNS) AS STAGING_ROWS
    UNION ALL SELECT 'FACT_SHIPMENTS' AS TABLE_NAME, (SELECT COUNT(*) FROM NOVAMART_DB.RAW.FACT_SHIPMENTS) AS RAW_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.STAGING.STG_FACT_SHIPMENTS) AS STAGING_ROWS
    UNION ALL SELECT 'FACT_WEB_EVENTS' AS TABLE_NAME, (SELECT COUNT(*) FROM NOVAMART_DB.RAW.FACT_WEB_EVENTS) AS RAW_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.STAGING.STG_FACT_WEB_EVENTS) AS STAGING_ROWS
)
SELECT TABLE_NAME, RAW_ROWS, STAGING_ROWS,
       IFF(RAW_ROWS = STAGING_ROWS, 'PASS', 'FAIL') AS CHECK_RESULT
FROM staging_counts
ORDER BY TABLE_NAME;

-- Curated and six analytics outputs: baseline expected counts.
WITH expected_counts AS (
    SELECT 'CURATED.FCT_RECOGNIZED_ORDERS' AS VIEW_NAME, 7395 AS EXPECTED_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.CURATED.FCT_RECOGNIZED_ORDERS) AS ACTUAL_ROWS
    UNION ALL SELECT 'CURATED.FCT_PROCESSED_REFUNDS' AS VIEW_NAME, 964 AS EXPECTED_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.CURATED.FCT_PROCESSED_REFUNDS) AS ACTUAL_ROWS
    UNION ALL SELECT 'CURATED.FCT_RECOGNIZED_ORDER_ITEMS' AS VIEW_NAME, 17965 AS EXPECTED_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.CURATED.FCT_RECOGNIZED_ORDER_ITEMS) AS ACTUAL_ROWS
    UNION ALL SELECT 'ANALYTICS.DAILY_SALES' AS VIEW_NAME, 669 AS EXPECTED_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.ANALYTICS.DAILY_SALES) AS ACTUAL_ROWS
    UNION ALL SELECT 'ANALYTICS.MONTHLY_REVENUE' AS VIEW_NAME, 22 AS EXPECTED_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.ANALYTICS.MONTHLY_REVENUE) AS ACTUAL_ROWS
    UNION ALL SELECT 'ANALYTICS.STORE_PERFORMANCE' AS VIEW_NAME, 22 AS EXPECTED_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.ANALYTICS.STORE_PERFORMANCE) AS ACTUAL_ROWS
    UNION ALL SELECT 'ANALYTICS.CHANNEL_PERFORMANCE' AS VIEW_NAME, 2 AS EXPECTED_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.ANALYTICS.CHANNEL_PERFORMANCE) AS ACTUAL_ROWS
    UNION ALL SELECT 'ANALYTICS.CUSTOMER_VALUE' AS VIEW_NAME, 2356 AS EXPECTED_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.ANALYTICS.CUSTOMER_VALUE) AS ACTUAL_ROWS
    UNION ALL SELECT 'ANALYTICS.CATEGORY_PERFORMANCE' AS VIEW_NAME, 12 AS EXPECTED_ROWS, (SELECT COUNT(*) FROM NOVAMART_DB.ANALYTICS.CATEGORY_PERFORMANCE) AS ACTUAL_ROWS
)
SELECT VIEW_NAME, EXPECTED_ROWS, ACTUAL_ROWS,
       IFF(EXPECTED_ROWS = ACTUAL_ROWS, 'PASS', 'FAIL') AS CHECK_RESULT
FROM expected_counts
ORDER BY VIEW_NAME;

-- Reconcile curated order revenue to item-level revenue. All amounts are INR, excluding tax.
WITH order_totals AS (
    SELECT SUM(GROSS_SALES_EX_TAX_INR) AS GROSS_SALES, SUM(PROCESSED_REFUNDS_EX_TAX_INR) AS REFUNDS, SUM(NET_REVENUE_INR) AS NET_REVENUE
    FROM NOVAMART_DB.CURATED.FCT_RECOGNIZED_ORDERS
),
item_totals AS (
    SELECT SUM(GROSS_SALES_EX_TAX_INR) AS GROSS_SALES, SUM(PROCESSED_REFUNDS_EX_TAX_INR) AS REFUNDS, SUM(NET_REVENUE_INR) AS NET_REVENUE
    FROM NOVAMART_DB.CURATED.FCT_RECOGNIZED_ORDER_ITEMS
)
SELECT
    IFF(o.GROSS_SALES = i.GROSS_SALES, 'PASS', 'FAIL') AS GROSS_SALES_MATCH,
    IFF(o.REFUNDS = i.REFUNDS, 'PASS', 'FAIL') AS REFUNDS_MATCH,
    IFF(o.NET_REVENUE = i.NET_REVENUE, 'PASS', 'FAIL') AS NET_REVENUE_MATCH,
    o.GROSS_SALES AS GROSS_SALES_INR,
    o.REFUNDS AS PROCESSED_REFUNDS_INR,
    o.NET_REVENUE AS NET_REVENUE_INR
FROM order_totals o CROSS JOIN item_totals i;

-- Independent exact baseline totals from the supplied analytics CSV files.
WITH actual AS (
 SELECT SUM(RECOGNIZED_ORDERS) AS RECOGNIZED_ORDERS,
        SUM(GROSS_SALES_EX_TAX_INR) AS GROSS_SALES,
        SUM(PROCESSED_REFUNDS_EX_TAX_INR) AS REFUNDS,
        SUM(NET_REVENUE_INR) AS NET_REVENUE
 FROM NOVAMART_DB.ANALYTICS.DAILY_SALES
)
SELECT RECOGNIZED_ORDERS, GROSS_SALES, REFUNDS, NET_REVENUE,
IFF(RECOGNIZED_ORDERS = 7395 AND GROSS_SALES = 677967524.69 AND REFUNDS = 35261224.01 AND NET_REVENUE = 642706300.68, 'PASS', 'FAIL') AS CHECK_RESULT
FROM actual;
